byte b = 127;              // 128 に変えてみよう(byte の範囲外でエラー)
short s = 32_000;
int i = 2_000_000_000;
long l = 9_000_000_000L;   // 末尾の L を消してみよう
float f = 3.14f;           // 末尾の f を消してみよう
double d = 3.14;
char c = 'J';              // 'J' を "J" に変えてみよう
boolean ok = true;

System.out.println("byte=" + b + " short=" + s + " int=" + i + " long=" + l);
System.out.println("float=" + f + " double=" + d + " char=" + c + " boolean=" + ok);

// 範囲はラッパークラスの定数で確認できる
System.out.println("int : " + Integer.MIN_VALUE + " 〜 " + Integer.MAX_VALUE);
System.out.println("long: " + Long.MIN_VALUE + " 〜 " + Long.MAX_VALUE);

// リテラルの書き方いろいろ(数字を変えてみよう)
System.out.println(0x1F);      // 16進数
System.out.println(0b1010);    // 2進数
System.out.println(1_000_000); // _ は桁区切り
System.out.println(010);       // 先頭0は8進数!10ではない

int count = 100;
long big = count;        // int → long:自動(拡大変換)
double rate = count;     // int → double:自動(拡大変換)
System.out.println(big + " / " + rate);

double price = 3.99;     // -3.99 や 3.5 に変えてみよう
int yen = (int) price;   // double → int はキャストが必要。小数点以下は切り捨て
System.out.println("(int) " + price + " = " + yen);

int value = 200;         // 127 や 256 に変えてみよう
byte small = (byte) value; // byte に入りきらない上位ビットは捨てられる
System.out.println("(byte) " + value + " = " + small);

System.out.println(7 / 2);   // int 同士の計算は int(詳しくは次のレッスン)
System.out.println(7 / 2.0); // 片方が double なら double

// int の最大値 + 1
System.out.println(Integer.MAX_VALUE + 1);

// 30日分のミリ秒。先頭の 1000 を 1000L に変えて再実行してみよう
long monthMillis = 1000 * 60 * 60 * 24 * 30;
System.out.println("30日 = " + monthMillis + " ミリ秒");

// double の誤差
System.out.println(0.1 + 0.2);
System.out.println(1.15 * 100);

// BigDecimal は文字列で作ると正確
java.math.BigDecimal x = new java.math.BigDecimal("0.1"); // "0.1" を 0.1(クォートなし)に変えてみよう
java.math.BigDecimal y = new java.math.BigDecimal("0.2");
System.out.println(x.add(y));

